class Soedinenie(sqlite3.Connection):
    """Own the process queue only while a write transaction is active."""

    def _pered_zapisyu(self, sql):
        if not _ua_sql_pishet(sql) or getattr(self, "_ua_zapis_v_ocheredi", False):
            return False
        vzyata = ZAMOK.acquire(timeout=ZAMOK_OZHIDANIE)
        if not vzyata:
            raise sqlite3.OperationalError("CRM thread queue timeout")
        self._ochered_vzyata = True
        try:
            _ua_fayl_zahvatit(ZAMOK_OZHIDANIE)
            self._fayl_zaregistrirovan = True
            self._ua_zapis_v_ocheredi = True
            return True
        except Exception:
            self._ochered_vzyata = False
            try:
                ZAMOK.release()
            except Exception:
                pass
            raise

    def _otpustit(self):
        self._ua_zapis_v_ocheredi = False
        if getattr(self, "_fayl_zaregistrirovan", False):
            self._fayl_zaregistrirovan = False
            try:
                _ua_fayl_otpustit()
            except Exception:
                pass
        if getattr(self, "_ochered_vzyata", False):
            self._ochered_vzyata = False
            try:
                ZAMOK.release()
            except Exception:
                pass

    def cursor(self, factory=None):
        return sqlite3.Connection.cursor(self, factory or _UaKursor)

    def execute(self, sql, parameters=()):
        novaya = self._pered_zapisyu(sql)
        try:
            return sqlite3.Connection.execute(self, sql, parameters)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def executemany(self, sql, seq_of_parameters):
        novaya = self._pered_zapisyu(sql)
        try:
            return sqlite3.Connection.executemany(self, sql, seq_of_parameters)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def executescript(self, sql_script):
        novaya = self._pered_zapisyu(sql_script)
        try:
            return sqlite3.Connection.executescript(self, sql_script)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def _commit_s_povtorom(self):
        import time as _ua_time

        for attempt in range(5):
            try:
                sqlite3.Connection.commit(self)
                return
            except sqlite3.OperationalError as exc:
                text = str(exc).casefold()
                if "locked" not in text and "busy" not in text:
                    raise
                if attempt == 4:
                    raise
                _ua_time.sleep(0.15 * (2 ** attempt))

    def commit(self):
        try:
            self._commit_s_povtorom()
        except Exception:
            try:
                sqlite3.Connection.rollback(self)
            finally:
                self._otpustit()
            raise
        self._otpustit()

    def rollback(self):
        try:
            return sqlite3.Connection.rollback(self)
        finally:
            self._otpustit()

    def close(self):
        try:
            if self.in_transaction:
                sqlite3.Connection.rollback(self)
            sqlite3.Connection.close(self)
        finally:
            self._otpustit()

    def __exit__(self, tip, znachenie, sled):
        try:
            if tip is None:
                self.commit()
            else:
                self.rollback()
        finally:
            try:
                self.close()
            except Exception:
                self._otpustit()
        return False

    def __del__(self):
        self._otpustit()

def connect():
    conn = sqlite3.connect(DB_FILE, timeout=ZAMOK_OZHIDANIE, factory=Soedinenie)
    conn.row_factory = sqlite3.Row
    # Setup pragmas must not hold the transaction queue for a long-lived reader.
    try:
        sqlite3.Connection.execute(conn, "PRAGMA journal_mode=DELETE")
    except Exception:
        pass
    sqlite3.Connection.execute(
        conn, "PRAGMA busy_timeout=%d" % (ZAMOK_OZHIDANIE * 1000)
    )
    sqlite3.Connection.execute(conn, "PRAGMA foreign_keys=ON")
    return conn

class _UaSoedinenie(sqlite3.Connection):
    def __init__(self, *a, **kw):
        sqlite3.Connection.__init__(self, *a, **kw)
        self._ua_baza = os.path.basename(str(a[0] if a else kw.get("database", "?")))
        self._ua_svoya = CEL in self._ua_baza
        self._ua_id = _novyy_id()
        self._ua_t0 = time.time()
        self._ua_kto = _kto(3)
        if self._ua_svoya:
            _dobavit(self._ua_id, self._ua_kto, self._ua_baza, self)
            _zapis("OPEN " + self._ua_id, 0.0, self._ua_baza + " | " + self._ua_kto)

    def commit(self):
        t0 = time.time()
        busy = "?"
        if self._ua_svoya:
            try:
                busy = self.execute("PRAGMA busy_timeout").fetchone()[0]
            except Exception:
                pass
        try:
            sqlite3.Connection.commit(self)
        except Exception as e:
            d = time.time() - t0
            _zapis("COMMIT_FAIL", d, self._ua_baza + " | " + self._ua_kto + " | " + repr(e))
            if self._ua_svoya:
                otchet_o_sboe(d, e, self._ua_kto, busy)
            raise
        d = time.time() - t0
        if self._ua_svoya:
            _zapis("COMMIT_OK " + self._ua_id, d, self._ua_kto)

    def close(self):
        try:
            if self._ua_svoya:
                _ubrat(self._ua_id)
                _zapis("CLOSE " + self._ua_id, time.time() - self._ua_t0, self._ua_kto)
        except Exception:
            pass
        sqlite3.Connection.close(self)

def _ua_connect(*a, **kw):
    if len(a) < 2 and "timeout" not in kw:
        kw["timeout"] = 30.0
    kw.setdefault("factory", _UaSoedinenie)
    con = _originalnyy_connect(*a, **kw)
    try:
        con.execute("PRAGMA busy_timeout=30000")
    except Exception:
        pass
    return con

def podklyuchit(g):
    try:
        ishodnyy = g.get("connect")
        if not callable(ishodnyy) or getattr(ishodnyy, "_ua_trace", False):
            return False

        def connect_s_trassoy(*a, **kw):
            return _Obertka(ishodnyy(*a, **kw), _kto(3))

        connect_s_trassoy._ua_trace = True
        connect_s_trassoy._ua_ishodnyy = ishodnyy
        g["connect"] = connect_s_trassoy
        _zapis("PODKLYUCHEN", 0.0, "db.connect обёрнут (V2)")
        return True
    except Exception as e:
        _zapis("PODKLYUCHENIE_FAIL", 0.0, repr(e))
        return False
